# Idempotent reconciler: observe, diff, apply only the differences.
desired = {"web": "t3.small", "db": "t3.large", "cache": "t3.micro"}
current = {"web": "t3.small", "old": "t2.nano"}      # the "cloud" (a dict here)

def make_plan(desired, current):
    plan = []
    for name, size in desired.items():
        if name not in current:
            plan.append(("create", name, size))
        elif current[name] != size:
            plan.append(("update", name, size))
    for name in current:
        if name not in desired:
            plan.append(("delete", name, None))
    return plan

def apply(plan, current):
    for action, name, size in plan:
        if action == "delete":
            current.pop(name, None)          # already gone counts as success
        else:
            current[name] = size

print("desired:", desired)
for run in (1, 2):
    plan = make_plan(desired, current)
    print("run", run, "plan:", plan)
    apply(plan, current)
print("final:", current)
print("second run changes:", len(make_plan(desired, current)))
